-- Generated by scripts/export-weekly-events-sql.mjs
-- Canonical seed for R Guide weekly event guides.

create table if not exists public.weekly_event_guides (
  id text primary key,
  city_id text not null,
  city_name text not null,
  country text,
  continent text,
  week_label text not null,
  sourced_at date not null,
  timezone text not null,
  refresh_cadence text not null default 'weekly',
  event_id text not null,
  event_title text not null,
  starts_at timestamptz not null,
  ends_at timestamptz,
  is_guide_worthy boolean not null default false,
  guide jsonb not null,
  raw_event jsonb not null,
  source_run jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.weekly_event_guides enable row level security;

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

do $$
begin
  create trigger weekly_event_guides_set_updated_at
  before update on public.weekly_event_guides
  for each row
  execute function public.set_updated_at();
exception
  when duplicate_object then null;
end;
$$;

do $$
begin
  create policy "Weekly event guides are readable"
  on public.weekly_event_guides
  for select
  using (true);
exception
  when duplicate_object then null;
end;
$$;

create index if not exists weekly_event_guides_city_week_idx on public.weekly_event_guides (city_id, sourced_at desc);
create index if not exists weekly_event_guides_starts_at_idx on public.weekly_event_guides (starts_at);
create index if not exists weekly_event_guides_guide_gin_idx on public.weekly_event_guides using gin (guide);

insert into public.weekly_event_guides (
  id,
  city_id,
  city_name,
  country,
  continent,
  week_label,
  sourced_at,
  timezone,
  refresh_cadence,
  event_id,
  event_title,
  starts_at,
  ends_at,
  is_guide_worthy,
  guide,
  raw_event,
  source_run
)
values
  ('event-barcelona-2026-05-docsbarcelona', 'barcelona', 'Barcelona', 'Spain', 'Europe', 'May 10-17, 2026', '2026-05-10'::date, 'Europe/Madrid', 'weekly', 'barcelona-2026-05-docsbarcelona', 'DocsBarcelona Festival', '2026-05-07T10:00:00+02:00'::timestamptz, '2026-05-17T23:00:00+02:00'::timestamptz, true, '{"id":"event-barcelona-2026-05-docsbarcelona","slug":"this-week-barcelona-docsbarcelona-festival","seoSlug":"this-week-barcelona-docsbarcelona-festival","seoTitle":"DocsBarcelona Festival in Barcelona","seoDescription":"DocsBarcelona Festival is happening during May 10-17, 2026. DocsBarcelona is the city''s documentary-film week, with screenings, talks, special sessions, filmmaker activity, and professional programming spread across Barcelona venues. Use it as a festival route: pick a day, choose one or two anchor screenings, then build the evening around the venue neighborhood.","title":"DocsBarcelona Festival: Full Schedule","photo":"https://docsbarcelona.com/wp-content/uploads/3622ecf9-e7eb-4c72-850a-b628dba315df-1.jpg","description":"DocsBarcelona is the city''s documentary-film week, with screenings, talks, special sessions, filmmaker activity, and professional programming spread across Barcelona venues. Use it as a festival route: pick a day, choose one or two anchor screenings, then build the evening around the venue neighborhood. Highlights: Opening film: A Fox Under a Pink Moon at Mooby Aribau. Mark Cousins Docs d''Honor retrospective at Filmoteca. Docs&City films connect Gaza, Barcelona, Tokyo, Granada, and other urban stories. Music-linked sessions at Casa Montjuic pair screenings with live performances. Closing night: Teatres de Campanya at CCCB Hall. Guide candidate: Multi-day, multi-venue festival with enough programming depth for a dedicated guide.","url":"https://docsbarcelona.com/en/festival/calendar/","category":"Activities","submissionType":"itinerary","itinerary":{"startDate":"2026-05-07","endDate":"2026-05-17"},"location":{"city":"Barcelona","neighborhood":"Citywide","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"r-events","name":"R Events","avatar":"/images/rguide-avatar.svg"},"upvotes":18,"createdAt":"2026-05-10","stops":[{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-07-2000-a-fox-under-a-pink-moon-1","name":"A Fox Under a Pink Moon","coordinates":[41.3867,2.1635],"description":"Opening-film thread about Soraya, a sixteen-year-old Afghan artist documenting her attempts to escape Iran and reunite with her mother in Austria. When: Thu, May 7, 8:00 PM. Venue: Mooby Aribau | Sala 5.","bookingUrl":"https://docsbarcelona.com/en/festival/calendar/","photo":"https://docsbarcelona.com/wp-content/uploads/3622ecf9-e7eb-4c72-850a-b628dba315df-1.jpg","eventTime":"Thu, May 7, 8:00 PM","eventVenue":"Mooby Aribau | Sala 5","itineraryDate":"2026-05-07","itineraryDay":1},{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-08-1800-the-story-of-documentary-film-2","name":"The Story of Documentary Film","coordinates":[41.3784,2.1713],"description":"Mark Cousins presents documentary cinema as a way to understand the last 120 years, from revolution and work to feminism, bodies, music, and fascism. When: Fri, May 8, 6:00 PM. Venue: Filmoteca | Sala Chomon.","bookingUrl":"https://docsbarcelona.com/en/festival/calendar/","photo":"https://docsbarcelona.com/wp-content/uploads/1adcc36f-e108-489d-bb8c-bd1868ce7440-1-scaled.jpg","eventTime":"Fri, May 8, 6:00 PM","eventVenue":"Filmoteca | Sala Chomon","itineraryDate":"2026-05-08","itineraryDay":2},{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-08-1830-cobijo-3","name":"Cobijo","coordinates":[41.3803,2.1609],"description":"A queer migration story following four people who fled toward the United States and rebuilt a fragile idea of home in Guatemala after harsh border policies blocked their plans. When: Fri, May 8, 6:30 PM. Venue: Renoir | Sala 6.","bookingUrl":"https://docsbarcelona.com/en/festival/calendar/","photo":"https://docsbarcelona.com/wp-content/uploads/cfc9fabc-a207-488a-acbd-9950f81c4e24-1-scaled.jpg","eventTime":"Fri, May 8, 6:30 PM","eventVenue":"Renoir | Sala 6","itineraryDate":"2026-05-08","itineraryDay":2},{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-08-1900-bestia-4","name":"Bestia","coordinates":[41.3803,2.1609],"description":"A portrait of three hunters in inland Catalonia that observes rural masculinity, contradiction, and the gap between traditional and urban mentalities. When: Fri, May 8, 7:00 PM. Venue: Renoir | Sala 5.","bookingUrl":"https://docsbarcelona.com/en/festival/calendar/","photo":"https://docsbarcelona.com/wp-content/uploads/8095c550-377d-4b61-8ec2-cf2047a56d6c-1.png","eventTime":"Fri, May 8, 7:00 PM","eventVenue":"Renoir | Sala 5","itineraryDate":"2026-05-08","itineraryDay":2},{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-08-2000-las-casas-en-mi-5","name":"Las casas en mi","coordinates":[41.3717,2.1589],"description":"Leon Guallart turns a tour of iconic twentieth-century architecture into a self-produced musical diary, paired in the festival with a live music performance. When: Fri, May 8, 8:00 PM. Venue: Casa Montjuic.","bookingUrl":"https://docsbarcelona.com/en/festival/calendar/","photo":"https://docsbarcelona.com/wp-content/uploads/c5b332b1-f67e-49e6-a111-2b8dee721734-1.jpg","eventTime":"Fri, May 8, 8:00 PM","eventVenue":"Casa Montjuic","itineraryDate":"2026-05-08","itineraryDay":2},{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-08-2045-80-angry-journalists-6","name":"80 Angry Journalists","coordinates":[41.3803,2.1609],"description":"A contemporary journalism story in the festival line of films that look beyond headlines and put human stakes behind public conflict. When: Fri, May 8, 8:45 PM. Venue: Renoir | Sala 6.","bookingUrl":"https://docsbarcelona.com/en/festival/calendar/","photo":"https://docsbarcelona.com/wp-content/uploads/a4250372-9918-47e9-afe3-23dd2834ff10-1.png","eventTime":"Fri, May 8, 8:45 PM","eventVenue":"Renoir | Sala 6","itineraryDate":"2026-05-08","itineraryDay":2},{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-08-2100-replica-7","name":"Replica","coordinates":[41.3803,2.1609],"description":"A technology-and-intimacy documentary about three women in contemporary China who turn to AI lovers and test the boundary between emotional freedom and dependence. When: Fri, May 8, 9:00 PM. Venue: Renoir | Sala 5.","bookingUrl":"https://docsbarcelona.com/en/festival/calendar/","photo":"https://docsbarcelona.com/wp-content/uploads/b2e18f29-e012-4a03-b8b6-fe875add12a7-1.jpg","eventTime":"Fri, May 8, 9:00 PM","eventVenue":"Renoir | Sala 5","itineraryDate":"2026-05-08","itineraryDay":2},{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-08-2100-les-culpables-8","name":"Les Culpables","coordinates":[41.383,2.1662],"description":"Marta Duran Lozano turns anonymous abortion testimonies into a collective screen space, using personal memory and staged voices to make silence visible. When: Fri, May 8, 9:00 PM. Venue: CCCB Teatre.","bookingUrl":"https://docsbarcelona.com/en/festival/calendar/","photo":"https://docsbarcelona.com/wp-content/uploads/7a0a9505-e4af-4537-9b66-7434580c0c87-1.jpg","eventTime":"Fri, May 8, 9:00 PM","eventVenue":"CCCB Teatre","itineraryDate":"2026-05-08","itineraryDay":2},{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-09-1800-abandonados-9","name":"Abandonados","coordinates":[41.3867,2.1635],"description":"Official calendar screening in the DocsBarcelona program. When: Sat, May 9, 6:00 PM. Venue: Mooby Aribau | Sala 5.","bookingUrl":"https://docsbarcelona.com/en/festival/calendar/","photo":"https://docsbarcelona.com/wp-content/uploads/7dcfab70-e509-4c42-945d-2d9abcede139-1.png","eventTime":"Sat, May 9, 6:00 PM","eventVenue":"Mooby Aribau | Sala 5","itineraryDate":"2026-05-09","itineraryDay":3},{"id":"barcelona-2026-05-docsbarcelona-docsbarcelona-2026-05-09-1830-whispers-in-the-woods-10","name":"Whispers 